// Neueste zuerst; das gespeicherte Protokoll-JSON wird für die UI ausgepackt.
const lesen = (t) => { try { return t ? JSON.parse(t) : null; } catch (e) { return null; } };
const protokolle = $input.all().map((i) => i.json).filter((r) => r.callId).map((r) => ({ ...r, protokoll: lesen(r.protokoll) }));
return [{ json: { protokolle, stand: new Date().toISOString() } }];

// Je Stelle: Stammdaten, Kriterien und Leitfaden in Reihenfolge (position).
const sauber = (r) => { const { id, createdAt, updatedAt, ...rest } = r; return rest; };
const alle = (name) => $(name).all().map((i) => i.json).filter((r) => r.assistantId).map(sauber);
const nachPosition = (a, b) => (Number(a.position) || 0) - (Number(b.position) || 0);
const kriterien = alle('Kriterien lesen');
const leitfaden = alle('Leitfaden lesen');
const stellen = alle('Stellen lesen').map((s) => ({
  ...s,
  kriterien: kriterien.filter((k) => k.assistantId === s.assistantId).sort(nachPosition),
  leitfaden: leitfaden.filter((l) => l.assistantId === s.assistantId).sort(nachPosition),
}));
return [{ json: { stellen } }];

// Prüft die Konfiguration einer Stelle aus der UI und bringt sie in die Form der Data Tables.
const b = $input.first().json.body ?? {};
const text = (v) => String(v ?? '').trim();
const zahl = (v) => {
  if (v === '' || v === null || v === undefined) return null;
  const n = Number(String(v).replace(',', '.'));
  return Number.isFinite(n) ? n : null;
};
const fehler = (meldung) => [{ json: { ok: false, fehler: meldung } }];

const id = text(b.assistantId);
if (!id) return fehler('Assistant-ID fehlt.');
const s = b.stelle ?? {};
if (!text(s.stelle)) return fehler('Die Bezeichnung der Stelle fehlt.');

const kriterien = (Array.isArray(b.kriterien) ? b.kriterien : []).filter((k) => text(k.kriterium)).map((k, i) => ({
  assistantId: id,
  position: i + 1,
  kriterium: text(k.kriterium),
  gewicht: zahl(k.gewicht),
  beschreibung: text(k.beschreibung),
  score1: text(k.score1),
  score2: text(k.score2),
  score3: text(k.score3),
  score4: text(k.score4),
  score5: text(k.score5),
}));
// Kriterium im Leitfaden immer in der Schreibweise des Kriteriums speichern.
const kanon = new Map(kriterien.map((k) => [k.kriterium.toLowerCase(), k.kriterium]));
const leitfaden = (Array.isArray(b.leitfaden) ? b.leitfaden : []).filter((l) => text(l.frage)).map((l, i) => ({
  assistantId: id,
  position: i + 1,
  thema: text(l.thema) || 'Frage ' + (i + 1),
  frage: text(l.frage),
  kriterium: kanon.get(text(l.kriterium).toLowerCase()) ?? text(l.kriterium),
  hinweis: text(l.hinweis),
}));
if (!kriterien.length) return fehler('Mindestens ein Bewertungskriterium ist nötig.');
if (!leitfaden.length) return fehler('Der Leitfaden braucht mindestens eine Frage.');

if (kanon.size !== kriterien.length) return fehler('Jedes Kriterium braucht einen eigenen Namen.');
const unbekannt = leitfaden.filter((l) => l.kriterium && !kanon.has(l.kriterium.toLowerCase()));
if (unbekannt.length) return fehler('Der Leitfaden verweist auf ein unbekanntes Kriterium: ' + unbekannt.map((l) => l.kriterium).join(', '));

const einladenAb = zahl(s.einladenAb) ?? 70;
const absageUnter = zahl(s.absageUnter) ?? 45;
if (absageUnter > einladenAb) return fehler('„Absage unter“ darf nicht über „Einladen ab“ liegen.');

return [{ json: {
  ok: true,
  assistantId: id,
  stelle: { assistantId: id, stelle: text(s.stelle), unternehmen: text(s.unternehmen), aufgaben: text(s.aufgaben), anforderungen: text(s.anforderungen), einladenAb, absageUnter },
  kriterien,
  leitfaden,
} }];

const e = $('Eingabe prüfen').first().json;
const fehler = $input.all().map((i) => i.json.error).find(Boolean);
return [{ json: { ok: true, assistantId: e.assistantId, kriterien: e.kriterien.length, fragen: e.leitfaden.length,
  sync: fehler ? 'fehler' : 'ok', syncFehler: fehler ? String(fehler.message ?? fehler) : null } }];

// Neue Stelle aus der UI: Bezeichnung und Vorlage (Assistant-ID einer bestehenden Stelle).
const b = $input.first().json.body ?? {};
const text = (v) => String(v ?? '').trim();
const stelle = text(b.stelle);
const vorlage = text(b.vorlage);
if (!stelle) return [{ json: { ok: false, fehler: 'Die Bezeichnung der Stelle fehlt.' } }];
if (!vorlage) return [{ json: { ok: false, fehler: 'Bitte eine Vorlage wählen.' } }];
return [{ json: { ok: true, stelle, vorlage } }];

// Neuer Assistant als Kopie der Vorlage: Technik und Gesprächsstil bleiben, alles Stellenbezogene wird neu gesetzt.
const n = $('Neue Stelle prüfen').first().json;
const { id, orgId, createdAt, updatedAt, isServerUrlSecretSet, latestVersion, ...a } = $input.first().json;
// "(m/w/d)" und ähnliche Klammern würde die Stimme sonst mit vorlesen.
const kurz = n.stelle.replace(/\s*\([^)]*\)/g, '').trim() || n.stelle;
const voll = 'Everlast Interview - ' + kurz;
const name = (voll.length <= 40 ? voll : kurz).slice(0, 40);
const jobId = kurz.toLowerCase().replace(/ä/g, 'ae').replace(/ö/g, 'oe').replace(/ü/g, 'ue').replace(/ß/g, 'ss').replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '');
const keyterms = ['Everlast', 'Everlast Consulting'];

const prompt = (a.model?.messages ?? []).find((m) => m.role === 'system');
if (!prompt) throw new Error('Die Vorlage hat keinen System-Prompt.');
const ersetzen = (text, start, ende, inhalt) => {
  const re = new RegExp('(' + start + '\\n)([\\s\\S]*?)(\\n' + ende + '\\n)');
  if (!re.test(text)) throw new Error('Abschnitt "' + start + '" fehlt im Prompt der Vorlage.');
  return text.replace(re, (m, kopf, alt, fuss) => kopf + '\n' + inhalt + '\n' + fuss);
};
// Bis der Sync gelaufen ist, kennt der Agent weder Stelle noch Fragen (Startwert wie in vapi/system-prompt.md).
let inhalt = ersetzen(prompt.content, '# Stelle', '# Leitfaden', 'Noch nicht synchronisiert. Du kennst keine Fakten zur Stelle.');
inhalt = ersetzen(inhalt, '# Leitfaden', '# Gesprächsregeln', 'Noch nicht synchronisiert. Sag der Person nach ihrer Antwort auf die Einwilligungsfrage, dass gerade ein technisches Problem besteht und sich das HR-Team bei ihr meldet. Beende dann das Gespräch.');

const transcriber = {
  ...a.transcriber,
  agentContext: 'Telefonisches Bewerbungsgespräch auf Deutsch für Everlast Consulting, Stelle ' + kurz + '. Bewerber nennen ihren Vor- und Nachnamen, oft nicht-deutsche Namen, manchmal buchstabiert.',
  keytermsPrompt: keyterms,
};
if (transcriber.fallbackPlan?.transcribers) {
  transcriber.fallbackPlan = {
    ...transcriber.fallbackPlan,
    transcribers: transcriber.fallbackPlan.transcribers.map((t) => (t.customVocabulary ? { ...t, customVocabulary: keyterms } : t)),
  };
}

return [{ json: { assistant: {
  ...a,
  name,
  firstMessage: 'Hallo und schön, dass du da bist! Ich bin der KI-Assistent von Everlast Consulting und führe heute das Gespräch mit dir für die Stelle ' + kurz + '. Kurz vorab: Das Gespräch wird aufgezeichnet und automatisch ausgewertet, die Entscheidung trifft aber immer unser HR-Team. Bist du damit einverstanden?',
  voicemailMessage: 'Hallo, hier ist der KI-Assistent von Everlast Consulting. Wir wollten mit dir ein Gespräch für die Stelle ' + kurz + ' führen. Wir melden uns noch einmal bei dir. Bis bald!',
  metadata: { ...(a.metadata ?? {}), jobId, jobTitle: n.stelle, configSource: 'UI, Kopie von ' + (a.name ?? n.vorlage) },
  transcriber,
  model: { ...a.model, messages: a.model.messages.map((m) => (m === prompt ? { ...m, content: inhalt } : m)) },
} } }];

// Unternehmen und Schwellen kommen aus der Vorlage; Aufgaben und Anforderungen sind stellenspezifisch und bleiben leer.
const v = $('Vorlage: Stelle lesen').first()?.json ?? {};
return [{ json: {
  assistantId: $input.first().json.id,
  stelle: $('Neue Stelle prüfen').first().json.stelle,
  unternehmen: v.unternehmen ?? '',
  aufgaben: '',
  anforderungen: '',
  einladenAb: v.einladenAb ?? 70,
  absageUnter: v.absageUnter ?? 45,
} }];

const a = $('Assistant anlegen').first().json;
const fehler = $input.all().map((i) => i.json.error).find(Boolean);
return [{ json: { ok: true, assistantId: a.id, name: a.name, sync: fehler ? 'fehler' : 'ok', syncFehler: fehler ? String(fehler.message ?? fehler) : null } }];

// Löschen nur mit Assistant-ID und nur, wenn keine Telefonnummer auf den Assistant zeigt.
const id = String($('DELETE Stelle').first().json.query?.assistantId ?? '').trim();
if (!id) return [{ json: { ok: false, fehler: 'Assistant-ID fehlt.' } }];
const nummern = $input.all().map((i) => i.json).filter((p) => p.assistantId === id);
if (nummern.length) {
  return [{ json: { ok: false, fehler: 'Die Telefonnummer ' + nummern.map((p) => p.number ?? p.name ?? p.id).join(', ') + ' ist mit diesem Assistant verbunden. Stell sie in Vapi zuerst auf einen anderen Assistant um.' } }];
}
return [{ json: { ok: true, assistantId: id } }];

// 404: Den Assistant gibt es in Vapi schon nicht mehr; die Stelle wird trotzdem entfernt.
const r = $input.first().json;
const code = Number(r.statusCode);
const id = $('Löschen prüfen').first().json.assistantId;
if ((code >= 200 && code < 300) || code === 404) return [{ json: { ok: true, assistantId: id } }];
return [{ json: { ok: false, fehler: 'Vapi hat das Löschen abgelehnt (' + code + '): ' + (r.body?.message ?? JSON.stringify(r.body)) } }];
